changeSet.sql:
INSERT INTO permission (subject, active, deleted, version, created_at, updated_at, description_uz, description_ru, description_uz_cyril, description_kaa) SELECT 'EMPLOYEES', true, false, 0, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, u.description_uz, u.description_ru, u.description_uz_cyril, u.description_kaa FROM permission u WHERE u.subject = 'USER' ON CONFLICT (subject) DO UPDATE SET active = true, deleted = false, deleted_at = NULL, updated_at = CURRENT_TIMESTAMP, description_uz = COALESCE(permission.description_uz, EXCLUDED.description_uz), description_ru = COALESCE(permission.description_ru, EXCLUDED.description_ru), description_uz_cyril = COALESCE(permission.description_uz_cyril, EXCLUDED.description_uz_cyril), description_kaa = COALESCE(permission.description_kaa, EXCLUDED.description_kaa);
INSERT INTO role_permissions (role_id, permission_id, version, created_at, updated_at) SELECT DISTINCT rp.role_id, e.id, 0, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM role_permissions rp JOIN permission u ON u.id = rp.permission_id AND u.subject = 'USER' JOIN permission e ON e.subject = 'EMPLOYEES' ON CONFLICT (role_id, permission_id) DO NOTHING;
INSERT INTO role_permission_actions (role_permission_id, action_id) SELECT DISTINCT nrp.id, rpa.action_id FROM role_permissions rp JOIN permission u ON u.id = rp.permission_id AND u.subject = 'USER' JOIN role_permission_actions rpa ON rpa.role_permission_id = rp.id JOIN permission e ON e.subject = 'EMPLOYEES' JOIN role_permissions nrp ON nrp.role_id = rp.role_id AND nrp.permission_id = e.id ON CONFLICT (role_permission_id, action_id) DO NOTHING;
DELETE FROM role_permission_actions WHERE role_permission_id IN ( SELECT rp.id FROM role_permissions rp JOIN permission u ON u.id = rp.permission_id AND u.subject = 'USER' );
DELETE FROM role_permissions WHERE permission_id IN (SELECT id FROM permission WHERE subject = 'USER');
DELETE FROM permission WHERE subject = 'USER';
